import type { ColumnInstance, TableDispatch, TableState } from 'react-table';

import { useColumnsSizesActions } from './actions.js';
import {
  DATA_TABLE_DEFAULT_MIN_COLUMN_WIDTH,
  DATA_TABLE_DEFAULT_COLUMN_WIDTH,
} from '../../DataTable/constants.js';
import { getIsPrefixColumn, isActionColumn } from '../../utils/column-utils.js';

// this is an adjustment for the cell and column actions button, this is interfering with measure ref.
const CELL_WIDTH_ADJUSTMENT = 31;

/**
 * Produces a cellMeasure function that reports its width back to the
 * instance state by mutation to prevent multiple re-renders.
 */
export function measureCellRef(
  state: TableState,
  dispatch: TableDispatch,
  columnId: string,
  maxWidth: number,
  maxAutoWidth: number,
  width: number | undefined,
  allColumns: ColumnInstance[],
) {
  return (element: HTMLElement) => {
    // If there is an element and the element has not been measured yet,
    // we need to measure it and report the width back to the state.
    if (element) {
      // Need to queue to the next microtask to make sure the virtualizer is actually done
      // rendering. This is not ideal and should be adressed in the DataTableV2 layout engine properly.
      Promise.resolve().then(() => {
        updateCellWidthsByColumn(
          element,
          columnId,
          width,
          maxWidth,
          maxAutoWidth,
          allColumns,
          state,
        );

        // In order to only dispatch the finishedMeasuring once, we rely on a
        // mutable flag on the state, that will be flipped when the dispatch has
        // been called once.
        if (state.isMeasuringInProgress) {
          state.isMeasuringInProgress = false;
          // Note: using `requestAnimationFrame` it sometimes didn't trigger in apps - the
          // fix is using `setTimeout(..., 1)` instead of `requestAnimationFrame` (APPDEV-6991).
          setTimeout(
            () =>
              dispatch({
                type: useColumnsSizesActions.cellWidthMeasureDone,
                element,
              }),
            1,
          );
        }
      });
    }
  };
}

/**
 * Updates state.cellWidthsByColumn and allColumns width. If there is a configured width then that is used.
 * Otherwise if the element width is greater than the currently saved width, then the
 * element width is used.
 * @param element - current element.
 * @param columnId - id of the column.
 * @param width - configured width.
 * @param maxWidth - maximum column width.
 * @param maxAutoWidth - limits the autoWidth value.
 * @param allColumns - column width here is also updated.
 * @param state - state containing the saved cell widths.
 */
export function updateCellWidthsByColumn(
  element: HTMLElement,
  columnId: string,
  width: number | undefined,
  maxWidth: number,
  maxAutoWidth: number,
  allColumns: { id: string; width?: number }[],
  state: { cellWidthsByColumn?: { [column: string]: number } },
): void {
  state.cellWidthsByColumn = state.cellWidthsByColumn ?? {};
  // Check if we have a configured width for the column with autoWidth
  const configuredWidth = width !== Number.MAX_SAFE_INTEGER ? width : undefined;
  if (configuredWidth) {
    // If we have a configured width on column definition beside autoWidth then use the configured width.
    state.cellWidthsByColumn[columnId] = configuredWidth;
    return;
  }

  const currentSavedWidth =
    state.cellWidthsByColumn[columnId] ?? DATA_TABLE_DEFAULT_MIN_COLUMN_WIDTH;
  const currentElementWidth = element.getBoundingClientRect().width;
  if (currentSavedWidth < currentElementWidth) {
    // If the currently stored width is less than the one measured for the
    // element, save the measured width in the record.
    const elementWidth = getElementWidth(
      element,
      currentElementWidth,
      maxWidth,
      maxAutoWidth,
    );
    state.cellWidthsByColumn[columnId] = elementWidth;
    // Note: The following is necessary to avoid the first attempt at
    // resizing not working. If this assignment is missing, you can
    // for example see the issue in the "ColumnWidthContentAware" story, the
    // first time you try to resize a column.
    updateColumnWidth(allColumns, columnId, elementWidth);
  } else if (currentSavedWidth === currentElementWidth) {
    // This is necessary for case when user of Notebooks app hides/shows column
    // and then (tries to) resize column. In our own stories not reproducible.
    updateColumnWidth(allColumns, columnId, currentSavedWidth);
  }
}

/**
 * Finds column with given id in the allColumns object and updates its width.
 * @param allColumns -
 * @param columnId -
 * @param newWidth -
 */
export function updateColumnWidth(
  allColumns: { id: string; width?: number }[],
  columnId: string,
  newWidth: number,
): void {
  const match = allColumns.find((col) => col.id === columnId);
  if (match) {
    match.width = newWidth;
  }
}

function getElementWidth(
  element: HTMLElement,
  currentElementWidth: number,
  maxWidth: number,
  maxAutoWidth: number,
): number {
  const internalMaxWidth = maxAutoWidth < maxWidth ? maxAutoWidth : maxWidth;
  const isButton = element.parentElement instanceof HTMLButtonElement;
  const elementWidth = isButton
    ? currentElementWidth + CELL_WIDTH_ADJUSTMENT
    : currentElementWidth;

  return elementWidth <= internalMaxWidth ? elementWidth : internalMaxWidth;
}

/** Helper function that extracts a grid fraction for a cell/header. */
export function getGridRatioForColumn(column: ColumnInstance): string {
  // Check if we need to apply the ratio as a fraction of the parent
  if (column.parent && column.parent.columns) {
    const siblingRatioSum = column.parent.columns.reduce(
      (sum, column) => sum + (column.ratioWidth ?? 1),
      0,
    );
    const subRatio =
      ((column.parent.ratioWidth ?? 1) / siblingRatioSum) *
      (column.ratioWidth ?? 1);

    return `${subRatio}fr`;
  }

  // Check if the placeholder column also has a fraction definition
  return column.placeholderOf
    ? `${column.placeholderOf.ratioWidth ?? 1}fr`
    : `${column.ratioWidth ?? 1}fr`;
}

/** Creates a a grid template string based on the various sizing mechanisms for columns. */
export function createColumnGridTemplate(
  visibleColumns: ColumnInstance[],
  lastHeaderId: string | undefined,
  hasRatioWidthsDefined: boolean,
  cellWidthsByColumn?: Record<string, number>,
  resizedColumnWidths?: Record<string, number>,
): string {
  // Collect the Grid template string
  let columnGridTemplate = '';

  // generate the grid template from the child header
  const columnTemplate = visibleColumns?.map((header) => {
    const ratio = getGridRatioForColumn(header);

    // find if the current column is the last column of the visible columns
    const isLastStandardColumn: boolean =
      !lastHeaderId || header.id.startsWith(lastHeaderId);

    // if the column is a prefix column, a ratio is defined, or the colum was already resized we can skip the rest
    if (getIsPrefixColumn(header.id)) {
      return header.width !== 0 && header.width !== undefined
        ? `${header.width}px`
        : '0fr';
    } else if (isActionColumn(header.id)) {
      return `${header.width}px`;
    } else if (header.ratioWidth !== undefined) {
      // define a minimum for the ratio width in case the table becomes scrollable
      return `minmax(${
        header.minWidth || DATA_TABLE_DEFAULT_MIN_COLUMN_WIDTH
      }px,${ratio})`;
    } else if (!isLastStandardColumn && resizedColumnWidths?.[header.id]) {
      return `${resizedColumnWidths[header.id]}px`;
    }

    // If no width is defined we default to DATA_TABLE_DEFAULT_COLUMN_WIDTH
    let columnWidth: number = DATA_TABLE_DEFAULT_COLUMN_WIDTH;

    // check all settings to get the correct width
    if (!header.width && header.autoWidth && !cellWidthsByColumn?.[header.id]) {
      return 'max-content';
    }

    if (isLastStandardColumn && !hasRatioWidthsDefined) {
      return 'auto';
    }

    if (header.autoWidth && cellWidthsByColumn?.[header.id]) {
      columnWidth = Math.ceil(cellWidthsByColumn[header.id]);
    }

    if (header.width) {
      columnWidth = header.width;
    }

    if (header.totalMinWidth && header.totalMinWidth > columnWidth) {
      columnWidth = header.totalMinWidth;
    }

    if (header.maxWidth && header.maxWidth < columnWidth) {
      columnWidth = header.maxWidth;
    }

    return `${columnWidth}px`;
  });

  columnGridTemplate = columnTemplate.join(' ');

  return columnGridTemplate;
}

/**
 * In order for the grid to remeasure the autoWidth columns, we need to
 * remove their header widths and remove the corresponding entry from cellWidthsByColumn
 * @param state - table state
 * @param childHeaderGroup - (child) header group used for creating the grid template
 * @returns - headersWithResetAutoWidth, filteredCellWidthsByColumn, isRemeasuringNeeded
 */
export function prepareColumnsForRemeasuring(
  state: TableState,
  childHeaderGroup: ColumnInstance[],
) {
  const {
    columnResizing: { columnWidths: resizedColumnWidths },
  } = state;
  let isRemeasuringNeeded = false;

  const headersWithResetAutoWidth = childHeaderGroup.map((header) => {
    const hasColumnBeenResized = resizedColumnWidths?.[header.id];
    if (
      (header.autoWidth && !hasColumnBeenResized) ||
      getIsPrefixColumn(header.id)
    ) {
      header.width = undefined;
      isRemeasuringNeeded = true;
    }
    return header;
  });

  return {
    headersWithResetAutoWidth,
    isRemeasuringNeeded,
  };
}
